// Safely extract the raw text from the OpenAI response
const item = $input.first();

let rawText = '';

try {
  // Standard OpenAI response structure: choices[0].message.content
  rawText = item.json.choices[0].message.content;
} catch (e) {
  rawText = '';
}

// Attempt to parse the JSON from OpenAI
let parsed;

try {
  // Strip any accidental markdown fences before parsing
  const cleaned = rawText
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();

  parsed = JSON.parse(cleaned);
} catch (parseError) {
  // Safe fallback — never let a parse failure break the pipeline
  parsed = {
    category: 'general',
    urgency: 'medium',
    sentiment: 'neutral',
    summary: 'Classification failed. Manual review required.',
    needs_human: true,
    suggested_action: 'Route to a human agent for manual classification.'
  };
}

// Validate and sanitize each field with fallbacks
const validCategories = ['billing', 'technical', 'onboarding', 'account', 'general'];
const validUrgency = ['low', 'medium', 'high'];
const validSentiment = ['positive', 'neutral', 'negative'];

const result = {
  category: validCategories.includes(parsed.category) ? parsed.category : 'general',
  urgency: validUrgency.includes(parsed.urgency) ? parsed.urgency : 'medium',
  sentiment: validSentiment.includes(parsed.sentiment) ? parsed.sentiment : 'neutral',
  summary: typeof parsed.summary === 'string' && parsed.summary.length > 0
    ? parsed.summary
    : 'No summary available.',
  needs_human: typeof parsed.needs_human === 'boolean' ? parsed.needs_human : true,
  suggested_action: typeof parsed.suggested_action === 'string' && parsed.suggested_action.length > 0
    ? parsed.suggested_action
    : 'Route to support team for review.'
};

return [{ json: result }];
